def run(state, number, chapter, notes, title, story_complete):
    outline = state.get("outline") or []
    next_state = dict(state)
    next_state["notes"] = notes
    next_state["chapter_count"] = number

    return {
        "next": {
            "state": next_state,
            "done": bool(story_complete) or number >= len(outline),
            "item": {"number": number, "title": title, "text": chapter},
        }
    }
